#### Phase 2: Application-Level Compression (Fine-Grained Control) - Week 2-3

**Objective**: Implement compression in ASP.NET Core applications for services not behind APIM or requiring endpoint-specific compression logic.

**Step 2.1 - Install Response Compression Packages** (Day 1)

Add required NuGet packages to ASP.NET Core project:

```powershell
# From PowerShell in project directory
dotnet add package Microsoft.AspNetCore.ResponseCompression --version 8.0.0
```

Package includes: gzip and deflate compression providers (built-in), brotli compression provider (recommended), compression middleware with content-type filtering and size thresholds.

**Step 2.2 - Configure Compression Middleware** (Day 1-2)

Add compression services and middleware to application startup:

```csharp
// Program.cs - ASP.NET Core 8
using Microsoft.AspNetCore.ResponseCompression;
using System.IO.Compression;

var builder = WebApplication.CreateBuilder(args);

// Add Response Compression services
builder.Services.AddResponseCompression(options =>
{
    // Enable compression for HTTPS (requires careful consideration for security)
    // Only enable if responses don't contain sensitive data or using additional protections
    options.EnableForHttps = true;

    // Add compression providers
    options.Providers.Add<BrotliCompressionProvider>();
    options.Providers.Add<GzipCompressionProvider>();

    // Define MIME types to compress
    options.MimeTypes = ResponseCompressionDefaults.MimeTypes.Concat(new[]
    {
        \"application/json\",
        \"application/xml\",
        \"text/xml\",
        \"text/csv\",
        \"application/fhir+json\" // FHIR-specific content type
    });
});

// Configure Brotli compression
builder.Services.Configure<BrotliCompressionProviderOptions>(options =>
{
    // Compression quality: 0 (fast, less compression) to 11 (slow, maximum compression)
    // Level 4-6 recommended for dynamic content (balances speed and compression)
    // Level 11 for static/cached content (maximum compression, acceptable CPU cost)
    options.Level = CompressionLevel.Optimal; // Maps to quality level 4
});

// Configure Gzip compression
builder.Services.Configure<GzipCompressionProviderOptions>(options =>
{
    // Compression level: Optimal (balance), Fastest (low CPU), SmallestSize (max compression)
    options.Level = CompressionLevel.Optimal; // Maps to level 6
});

var app = builder.Build();

// Use Response Compression middleware - MUST be early in pipeline
// Place before static files, MVC, etc. to compress all responses
app.UseResponseCompression();

// Other middleware
app.UseHttpsRedirection();
app.UseAuthentication();
app.UseAuthorization();

app.MapControllers();

app.Run();
```

**Step 2.3 - Implement Custom Compression Provider for Advanced Logic** (Day 2-3)

For fine-grained control (per-endpoint compression, adaptive compression levels, custom thresholds), create custom provider:

```csharp
// Services/AdaptiveCompressionProvider.cs
using Microsoft.AspNetCore.ResponseCompression;
using System.Diagnostics;
using System.IO.Compression;

namespace Gainwell.Api.Compression;

public class AdaptiveCompressionProvider : ICompressionProvider
{
    private readonly ILogger<AdaptiveCompressionProvider> _logger;
    private readonly AdaptiveCompressionOptions _options;

    public string EncodingName => \"gzip\";

    public AdaptiveCompressionProvider(
        ILogger<AdaptiveCompressionProvider> logger,
        IOptions<AdaptiveCompressionOptions> options)
    {
        _logger = logger;
        _options = options.Value;
    }

    public bool SupportsFlush => true;

    public Stream CreateStream(Stream outputStream)
    {
        // Determine compression level based on current system load
        var cpuUtilization = GetCpuUtilization();
        var compressionLevel = DetermineCompressionLevel(cpuUtilization);

        _logger.LogDebug(
            \"Creating compression stream: CPU={CpuPercent:F1}%, Level={Level}\",
            cpuUtilization, compressionLevel);

        return new GZipStream(outputStream, compressionLevel, leaveOpen: true);
    }

    private double GetCpuUtilization()
    {
        // Get current process CPU utilization
        using var process = Process.GetCurrentProcess();
        var startTime = DateTime.UtcNow;
        var startCpuUsage = process.TotalProcessorTime;

        Thread.Sleep(100); // Sample period

        var endTime = DateTime.UtcNow;
        var endCpuUsage = process.TotalProcessorTime;

        var cpuUsedMs = (endCpuUsage - startCpuUsage).TotalMilliseconds;
        var totalMsPassed = (endTime - startTime).TotalMilliseconds;
        var cpuUsageTotal = cpuUsedMs / (Environment.ProcessorCount * totalMsPassed);

        return cpuUsageTotal * 100;
    }

    private CompressionLevel DetermineCompressionLevel(double cpuUtilization)
    {
        // Adaptive compression based on CPU load
        return cpuUtilization switch
        {
            < 50 => CompressionLevel.SmallestSize,  // Low load: max compression (level 9)
            < 75 => CompressionLevel.Optimal,        // Medium load: balanced (level 6)
            < 90 => CompressionLevel.Fastest,        // High load: fast compression (level 3)
            _ => CompressionLevel.NoCompression      // Critical load: disable compression
        };
    }
}

public class AdaptiveCompressionOptions
{
    public double LowLoadThreshold { get; set; } = 50;
    public double MediumLoadThreshold { get; set; } = 75;
    public double HighLoadThreshold { get; set; } = 90;
}

// Register in Program.cs
builder.Services.AddSingleton<ICompressionProvider, AdaptiveCompressionProvider>();
builder.Services.Configure<AdaptiveCompressionOptions>(
    builder.Configuration.GetSection(\"AdaptiveCompression\"));
```

**Step 2.4 - Add Compression Metrics** (Day 3-4)

Instrument compression middleware to track effectiveness:

```csharp
// Middleware/CompressionMetricsMiddleware.cs
using Microsoft.AspNetCore.Http;
using Prometheus;

namespace Gainwell.Api.Middleware;

public class CompressionMetricsMiddleware
{
    private readonly RequestDelegate _next;

    // Prometheus metrics
    private static readonly Counter CompressedResponses = Metrics.CreateCounter(
        \"http_responses_compressed_total\",
        \"Total responses compressed\",
        new CounterConfiguration { LabelNames = new[] { \"content_type\", \"algorithm\" } });

    private static readonly Histogram CompressionRatio = Metrics.CreateHistogram(
        \"http_compression_ratio_percent\",
        \"Response compression ratio percentage\",
        new HistogramConfiguration
        {
            LabelNames = new[] { \"content_type\" },
            Buckets = new[] { 50, 60, 70, 75, 80, 85, 90, 95 }
        });

    private static readonly Histogram CompressionDuration = Metrics.CreateHistogram(
        \"http_compression_duration_milliseconds\",
        \"Time taken to compress response\",
        new HistogramConfiguration
        {
            Buckets = Histogram.ExponentialBuckets(0.1, 2, 10) // 0.1ms to 51ms
        });

    private static readonly Counter BandwidthSaved = Metrics.CreateCounter(
        \"http_compression_bandwidth_saved_bytes\",
        \"Total bandwidth saved through compression\");

    public CompressionMetricsMiddleware(RequestDelegate next)
    {
        _next = next;
    }

    public async Task InvokeAsync(HttpContext context)
    {
        var originalBodyStream = context.Response.Body;

        using var responseBody = new MemoryStream();
        context.Response.Body = responseBody;

        var stopwatch = Stopwatch.StartNew();

        await _next(context);

        stopwatch.Stop();

        // Check if response was compressed
        var contentEncoding = context.Response.Headers[\"Content-Encoding\"].ToString();
        var isCompressed = !string.IsNullOrEmpty(contentEncoding);

        if (isCompressed)
        {
            var contentType = context.Response.ContentType ?? \"unknown\";
            var compressedSize = responseBody.Length;

            // Attempt to determine uncompressed size from custom header if available
            var uncompressedSize = compressedSize;
            if (context.Response.Headers.ContainsKey(\"X-Uncompressed-Size\"))
            {
                if (long.TryParse(context.Response.Headers[\"X-Uncompressed-Size\"], out var size))
                {
                    uncompressedSize = size;
                }
            }

            if (uncompressedSize > compressedSize)
            {
                var ratio = (1 - (double)compressedSize / uncompressedSize) * 100;
                var saved = uncompressedSize - compressedSize;

                // Record metrics
                CompressedResponses.WithLabels(contentType, contentEncoding).Inc();
                CompressionRatio.WithLabels(contentType).Observe(ratio);
                CompressionDuration.Observe(stopwatch.Elapsed.TotalMilliseconds);
                BandwidthSaved.Inc(saved);
            }
        }

        responseBody.Seek(0, SeekOrigin.Begin);
        await responseBody.CopyToAsync(originalBodyStream);
    }
}

// Register in Program.cs
app.UseMiddleware<CompressionMetricsMiddleware>();
```

**Step 2.5 - Testing and Validation** (Day 4-5)

Create comprehensive tests validating compression behavior:

```csharp
// Tests/CompressionTests.cs
using Microsoft.AspNetCore.Mvc.Testing;
using System.IO.Compression;
using Xunit;

namespace Gainwell.Api.Tests;

public class CompressionTests : IClassFixture<WebApplicationFactory<Program>>
{
    private readonly WebApplicationFactory<Program> _factory;

    public CompressionTests(WebApplicationFactory<Program> factory)
    {
        _factory = factory;
    }

    [Fact]
    public async Task LargeJsonResponse_WithGzipAcceptEncoding_ReturnsCompressed()
    {
        // Arrange
        var client = _factory.CreateClient();
        client.DefaultRequestHeaders.Add(\"Accept-Encoding\", \"gzip\");

        // Act
        var response = await client.GetAsync(\"/api/providers/search?city=Orlando\");

        // Assert
        Assert.Equal(System.Net.HttpStatusCode.OK, response.StatusCode);
        Assert.Equal(\"gzip\", response.Content.Headers.ContentEncoding.FirstOrDefault());
        Assert.Contains(\"Accept-Encoding\", response.Headers.Vary);

        // Verify decompression works
        await using var stream = await response.Content.ReadAsStreamAsync();
        await using var decompressedStream = new GZipStream(stream, CompressionMode.Decompress);
        using var reader = new StreamReader(decompressedStream);
        var content = await reader.ReadToEndAsync();

        Assert.NotEmpty(content);
        Assert.Contains(\"providers\", content); // Validate JSON structure
    }

    [Fact]
    public async Task SmallResponse_BelowThreshold_NoCompression()
    {
        // Arrange
        var client = _factory.CreateClient();
        client.DefaultRequestHeaders.Add(\"Accept-Encoding\", \"gzip\");

        // Act (health check typically <1KB)
        var response = await client.GetAsync(\"/health\");

        // Assert
        Assert.Equal(System.Net.HttpStatusCode.OK, response.StatusCode);
        Assert.Empty(response.Content.Headers.ContentEncoding); // No compression
    }

    [Fact]
    public async Task LegacyClient_NoAcceptEncoding_UncompressedResponse()
    {
        // Arrange
        var client = _factory.CreateClient();
        // Deliberately omit Accept-Encoding header (legacy client)

        // Act
        var response = await client.GetAsync(\"/api/providers/search\");

        // Assert
        Assert.Equal(System.Net.HttpStatusCode.OK, response.StatusCode);
        Assert.Empty(response.Content.Headers.ContentEncoding); // No compression

        // Response should be valid JSON directly
        var content = await response.Content.ReadAsStringAsync();
        Assert.NotEmpty(content);
        Assert.Contains(\"providers\", content);
    }

    [Theory]
    [InlineData(\"image/jpeg\")]
    [InlineData(\"image/png\")]
    [InlineData(\"application/pdf\")]
    public async Task BinaryContent_NeverCompressed(string contentType)
    {
        // Test that already-compressed content types are excluded
        // (Implementation depends on serving such content from API)
    }
}
